package com.clavis.reader;
import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import androidx.recyclerview.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Chart-based discovery with instant local results and debounced online search. */
final class PodcastDirectory {
 static final ExecutorService network=Executors.newFixedThreadPool(2);
 static JSONArray entries(Context c)throws Exception{try(InputStream in=c.getAssets().open("rss/podcasts.json")){return new JSONArray(new String(FeedCatalog.readBytes(in),java.nio.charset.StandardCharsets.UTF_8));}}
 static ArrayList<JSONObject> filter(JSONArray entries,String query)throws Exception{ArrayList<JSONObject> out=new ArrayList<>();String[] words=query.toLowerCase(Locale.ROOT).trim().split("\\s+");for(int n=0;n<entries.length();n++){JSONObject e=entries.getJSONObject(n);String hay=(e.optString("title")+" "+e.optString("artist")+" "+e.optJSONArray("tags")).toLowerCase(Locale.ROOT);boolean matches=true;for(String word:words)if(!hay.contains(word))matches=false;if(matches)out.add(e);}return out;}
 static synchronized void seed(Context c){android.content.SharedPreferences prefs=c.getSharedPreferences("rss_feeds",0);if(prefs.getBoolean("podcast_defaults_v4",false))return;try{HashSet<String> legacy=new HashSet<>();try(InputStream in=c.getAssets().open("rss/legacy-podcasts-v3.json")){JSONArray old=new JSONArray(new String(FeedCatalog.readBytes(in),java.nio.charset.StandardCharsets.UTF_8));for(int n=0;n<old.length();n++)legacy.add(old.getString(n));}ArrayList<FeedStore.Feed> saved=FeedStore.load(c);boolean existingInstall=prefs.getBoolean("starter_v1",false);JSONArray defaults=entries(c);for(int n=0;n<50;n++){JSONObject e=defaults.getJSONObject(n);String url=e.getString("url");boolean found=false;for(FeedStore.Feed feed:saved)if(feed.kind.equals("Podcasts")&&feed.url.equals(url)){found=true;break;}if(found||existingInstall&&legacy.contains(url))continue;FeedStore.Feed feed=new FeedStore.Feed();feed.kind="Podcasts";feed.title=e.getString("title");feed.url=url;feed.image=e.optString("image");saved.add(feed);}FeedStore.save(c,saved);prefs.edit().putBoolean("podcast_defaults_v4",true).apply();}catch(Exception error){android.util.Log.e("ClavisRSS","Could not seed podcast directory",error);}}
 static void show(MainActivity a){a.screen="Podcasts browse";a.shell("Podcasts");a.bar.removeViewAt(2);View old=a.root.getChildAt(1);a.root.removeView(old);LinearLayout page=a.column();a.root.addView(page,new LinearLayout.LayoutParams(-1,0,1));FeedScreens.tabs(a,"Podcasts",false,true);
  LinearLayout controls=a.column();controls.setPadding(a.dp(16),0,a.dp(16),a.dp(4));EditText search=new EditText(a);search.setSingleLine();search.setTextSize(14);search.setMinHeight(a.dp(44));search.setPadding(a.dp(8),a.dp(4),a.dp(8),a.dp(4));search.setHint("Search 500 podcasts and online");search.setContentDescription("Search podcast catalog and online");search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);controls.addView(search,new LinearLayout.LayoutParams(-1,-2));TextView status=a.text("500 chart picks · US, India and UK",12,MainActivity.MUTED,false);status.setTextSize(11);status.setMaxLines(2);status.setEllipsize(TextUtils.TruncateAt.END);status.setPadding(a.dp(4),a.dp(2),a.dp(4),a.dp(2));controls.addView(status);page.addView(controls);
  RecyclerView list=new RecyclerView(a);list.setLayoutManager(new LinearLayoutManager(a));list.setClipToPadding(false);list.setPadding(a.dp(16),0,a.dp(16),a.dp(104));page.addView(list,new LinearLayout.LayoutParams(-1,0,1));DirectoryAdapter adapter=new DirectoryAdapter(a);list.setAdapter(adapter);Handler handler=new Handler(Looper.getMainLooper());final int[] generation={0};final Runnable[] pending={null};final JSONArray catalog;try{catalog=entries(a);}catch(Exception e){status.setText("Catalog unavailable. Try online search.");return;}
  Runnable render=()->{int token=++generation[0];if(pending[0]!=null)handler.removeCallbacks(pending[0]);String query=search.getText().toString().trim();try{adapter.set(filter(catalog,query));}catch(Exception ignored){}list.scrollToPosition(0);if(query.isEmpty()){status.setText("500 chart picks · US, India and UK");return;}int local=adapter.rows.size();if(query.length()<2){status.setText(local+" catalog matches · type 2 letters to search online");return;}status.setText(local+" catalog matches · searching online…");pending[0]=()->network.execute(()->{try{JSONArray online=online(query);handler.post(()->{if(token!=generation[0]||!list.isAttachedToWindow()||a.isDestroyed())return;int added=adapter.append(online);status.setText(local+" catalog matches · "+added+" more online");});}catch(Exception error){handler.post(()->{if(token==generation[0]&&list.isAttachedToWindow())status.setText(local+" catalog matches · online unavailable, try again");});}});handler.postDelayed(pending[0],650);};
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){render.run();}public void afterTextChanged(Editable e){}});search.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH){render.run();if(pending[0]!=null){handler.removeCallbacks(pending[0]);pending[0].run();}return true;}return false;});list.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){generation[0]++;if(pending[0]!=null)handler.removeCallbacks(pending[0]);}});render.run();a.miniPlayer();
 }
 static JSONArray online(String query)throws Exception{String url="https://itunes.apple.com/search?media=podcast&entity=podcast&limit=50&term="+android.net.Uri.encode(query);JSONArray results=new JSONObject(new String(FeedStore.fetch(url,3*1024*1024),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("results"),out=new JSONArray();for(int n=0;n<results.length();n++){JSONObject r=results.getJSONObject(n);String feed=FeedStore.web(r.optString("feedUrl"));if(!feed.startsWith("https://"))continue;out.put(new JSONObject().put("kind","Podcasts").put("title",r.optString("collectionName","Podcast")).put("url",feed).put("image",r.optString("artworkUrl600",r.optString("artworkUrl100"))).put("artist",r.optString("artistName")));}return out;}
 static final class DirectoryAdapter extends RecyclerView.Adapter<Row>{final MainActivity a;final ArrayList<JSONObject> rows=new ArrayList<>();final HashSet<String> subscribed=new HashSet<>();DirectoryAdapter(MainActivity a){this.a=a;reload();}void reload(){subscribed.clear();for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals("Podcasts"))subscribed.add(feed.url);}void set(List<JSONObject> items){rows.clear();rows.addAll(items);notifyDataSetChanged();}int append(JSONArray entries){HashSet<String> seen=new HashSet<>();for(JSONObject e:rows)seen.add(e.optString("url"));int start=rows.size();for(int n=0;n<entries.length();n++){JSONObject e=entries.optJSONObject(n);if(e!=null&&seen.add(e.optString("url")))rows.add(e);}if(rows.size()>start)notifyItemRangeInserted(start,rows.size()-start);return rows.size()-start;}public int getItemCount(){return rows.size();}public Row onCreateViewHolder(ViewGroup parent,int type){return new Row(a);}public void onBindViewHolder(Row h,int pos){JSONObject e=rows.get(pos);h.title.setText(e.optString("title"));HindiTypography.apply(h.title,h.title.getText().toString());h.artist.setText(e.optString("artist"));boolean added=subscribed.contains(e.optString("url"));h.action.setText(added?"Added":"Follow");h.action.setContentDescription((added?"Open ":"Follow ")+e.optString("title"));h.art.setTag(null);h.art.setImageDrawable(null);h.art.setImageResource(R.drawable.ic_podcast);FeedArtwork.bind(a,h.art,e.optString("image"));h.itemView.setOnClickListener(v->select(e));h.action.setOnClickListener(v->select(e));}void select(JSONObject e){String url=e.optString("url");for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals("Podcasts")&&feed.url.equals(url)){FeedScreens.items(a,feed);return;}ProgressDialog progress=new ProgressDialog(a);progress.setMessage("Adding "+e.optString("title")+"…");progress.setCancelable(false);progress.show();network.execute(()->{try{FeedStore.Feed feed=FeedStore.download(url,"Podcasts");feed.title=e.optString("title");if(feed.image.isEmpty())feed.image=e.optString("image");FeedStore.put(a,feed);a.runOnUiThread(()->{if(a.isDestroyed())return;progress.dismiss();reload();notifyDataSetChanged();AppNotice.makeText(a,"Podcast added to My podcasts",Toast.LENGTH_SHORT).show();});}catch(Exception error){a.runOnUiThread(()->{if(a.isDestroyed())return;progress.dismiss();new AppDialog.Builder(a).setTitle("Could not add podcast").setMessage("Check your connection and try again.").setPositiveButton("Close",null).show();});}});}}
 static final class Row extends RecyclerView.ViewHolder{final ImageView art;final TextView title,artist,action;Row(MainActivity a){super(a.row());LinearLayout row=(LinearLayout)itemView;row.setPadding(a.dp(12),a.dp(10),a.dp(12),a.dp(10));row.setGravity(Gravity.CENTER_VERTICAL);row.setBackground(UiStyle.surface(a,"Podcasts",16));RecyclerView.LayoutParams params=new RecyclerView.LayoutParams(-1,-2);params.bottomMargin=a.dp(8);row.setLayoutParams(params);art=FeedIcons.tile(a,"Podcast");row.addView(art,new LinearLayout.LayoutParams(a.dp(58),a.dp(58)));LinearLayout copy=a.column();title=a.text("",15,MainActivity.INK,true);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);artist=a.text("",12,MainActivity.MUTED,false);artist.setMaxLines(1);artist.setEllipsize(TextUtils.TruncateAt.END);copy.addView(title);copy.addView(artist);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.leftMargin=a.dp(12);cp.rightMargin=a.dp(8);row.addView(copy,cp);action=a.button("Follow",()->{});action.setTextSize(12);row.addView(action,new LinearLayout.LayoutParams(a.dp(68),a.dp(48)));}}
}
